              set now = $ZDATE($NOW(), 3)

              set dobYear = $SYSTEM.SQL.YEAR($ZDATEH(dateOfBirth,8))
   ///    $$$TRACE("DOB year: " _ dobYear)
   ///           $$$TRACE("Dob year: " _ dobYear)
              set thisYear = $SYSTEM.SQL.YEAR(now)
  ///           $$$TRACE("This year: " _ thisYear)
              set dobMonth = ($SYSTEM.SQL.MONTH($ZDATEH(dateOfBirth,8)))
  ///            $$$TRACE("Dob month: " _ dobMonth)
              set thisMonth = ($SYSTEM.SQL.MONTH(now))
  ///            $$$TRACE("This month: " _ thisMonth)
              set dobDay = ($SYSTEM.SQL.DAYOFMONTH($ZDATEH(dateOfBirth,8)))

              set thisDay = ($SYSTEM.SQL.DAYOFMONTH(now))

              set age = thisYear - dobYear

              if (dobMonth = thisMonth)
              {
  ///                   $$$TRACE("Dob month is equal to this month")

                      if (dobDay > thisDay)
                      {
  ///                            $$$TRACE("Persons birthday hasn't passed this year")
                              set age = age - 1
                      }
              }


///              $$$TRACE("Age is " _ age)

              quit age
